css:
.print-format { font-family: Arial, "Noto Sans Arabic", sans-serif; color: #111; }
.official-duty-form { direction: rtl; font-size: 10.5px; line-height: 1.35; }
.letter-head-wrap { margin-bottom: 8px; }
.form-title {
    border: 1.6px solid #111;
    text-align: center;
    font-size: 15px;
    font-weight: 700;
    padding: 5px 8px;
    background: #f1f1f1;
}
.form-meta { display: flex; justify-content: space-between; font-size: 9px; margin: 4px 1px 7px; }
.official-table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.official-table th, .official-table td {
    border: 1px solid #222;
    padding: 5px 6px;
    vertical-align: top;
}
.official-table th {
    width: 22%;
    background: #f5f5f5;
    font-weight: 700;
    text-align: center;
}
.label-en { display: block; direction: ltr; font-size: 8px; font-weight: 600; margin-top: 1px; }
.value { min-height: 18px; font-weight: 600; }
.long-box { min-height: 70px; white-space: pre-wrap; font-weight: normal; }
.report-box { min-height: 90px; white-space: normal; font-weight: normal; }
.signature-row { display: flex; gap: 8px; align-items: flex-end; }
.signature-cell { flex: 1; min-height: 50px; }
.signature-name { min-height: 18px; text-align: center; font-weight: 700; }
.signature-line { border-top: 1px dotted #111; margin: 12px 3px 3px; }
.signature-caption { text-align: center; font-size: 8px; }
.muted { color: #555; font-size: 8px; }
.approvals-title {
    text-align: center;
    border: 1px solid #222;
    border-top: 0;
    font-weight: 700;
    padding: 4px;
    background: #eee;
}
.footer-line { display: flex; justify-content: space-between; border-top: 1px solid #aaa; margin-top: 7px; padding-top: 4px; font-size: 8px; color: #555; }
@media print {
    .official-duty-form { page-break-inside: avoid; }
    .official-table tr { page-break-inside: avoid; }
}
.center { text-align: center; }
.report-heading-row th { background: #e9e9e9; font-size: 11px; }
.revision-box { min-height: 42px; white-space: pre-wrap; }

    .official-duty-form .report-box p { margin: 0 0 7px; }
    .official-duty-form .report-box ul,
    .official-duty-form .report-box ol { margin: 5px 18px 8px 0; padding-right: 18px; }
    .official-duty-form .report-box table { width: 100%; border-collapse: collapse; margin-top: 8px; }
    .official-duty-form .report-box table td,
    .official-duty-form .report-box table th { border: 1px solid #777; padding: 5px; }

.approval-role {
    min-height: 14px;
    margin-bottom: 3px;
    text-align: center;
    font-size: 8.5px;
    font-weight: 700;
    color: #333;
}

.bypass-text { font-size: 9px; font-weight: 700; line-height: 1.4; }


.bypass-box {
    min-height: 48px;
    padding: 7px 8px;
    border: 1px dashed #666;
    background: #f7f7f7;
    text-align: center;
    font-size: 8.5px;
    line-height: 1.55;
}
.bypass-title {
    margin-bottom: 3px;
    font-weight: 700;
}
